// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Log lg;
    bytes4 constant HIST_SEL = bytes4(keccak256("History(uint256)"));

    function setUp() public {
        lg = new Log();
        c = new MY_BANK(address(lg));
    }

    function testFuzz_property(uint256 amount, uint256 warpTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(lg));
        amount = bound(amount, 1, 100 ether);
        warpTime = bound(warpTime, block.timestamp + 1, block.timestamp + 365 days);

        vm.deal(actor, amount);
        vm.warp(warpTime);
        vm.prank(actor);
        c.Put{value: amount}(warpTime + 1 hours);

        // The log must contain an entry stamped with this exact deposit time,
        // crediting this exact actor and amount.
        (bool ok, bytes memory ret) = address(lg).staticcall(abi.encodeWithSelector(HIST_SEL, 0));
        bool recorded = false;
        if (ok && ret.length >= 32 * 4) {
            (address s, , uint256 v, uint256 t) = abi.decode(ret, (address, string, uint256, uint256));
            recorded = (s == actor && v == amount && t == warpTime);
        }
        assertTrue(recorded);
    }
}
